const cluster_id = 'REPLACE_WITH_CLUSTER_ID_TO_REQUEUE';
const review_interface = 'REPLACE_WITH_REVIEW_INTERFACE_TO_REQUEUE';
const delivery_channel = 'REPLACE_WITH_DELIVERY_CHANNEL_TO_REQUEUE';
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(cluster_id)) throw new Error('Replace REPLACE_WITH_CLUSTER_ID_TO_REQUEUE with a cluster UUID before executing');
if (!['slack','telegram'].includes(review_interface)) throw new Error('Review interface must be slack or telegram');
if (!['slack','telegram'].includes(delivery_channel)) throw new Error('Delivery channel must be slack or telegram');
return [{ json: { cluster_id, review_interface, delivery_channel, requeue_reason: 'operator_provider_recovery' } }];
